public class InnerConnectionConnectionPropertiesInputFactory(Action<Humidifier.DataZone.ConnectionTypes.ConnectionPropertiesInput> factoryAction = null) : SubResourceFactory<Humidifier.DataZone.ConnectionTypes.ConnectionPropertiesInput>
{

    internal InnerConnectionIamPropertiesInputFactory IamPropertiesFactory { get; set; }

    internal InnerConnectionHyperPodPropertiesInputFactory HyperPodPropertiesFactory { get; set; }

    internal InnerConnectionSparkGluePropertiesInputFactory SparkGluePropertiesFactory { get; set; }

    internal InnerConnectionMlflowPropertiesInputFactory MlflowPropertiesFactory { get; set; }

    internal InnerConnectionAthenaPropertiesInputFactory AthenaPropertiesFactory { get; set; }

    internal InnerConnectionRedshiftPropertiesInputFactory RedshiftPropertiesFactory { get; set; }

    internal InnerConnectionWorkflowsMwaaPropertiesInputFactory WorkflowsMwaaPropertiesFactory { get; set; }

    internal InnerConnectionAmazonQPropertiesInputFactory AmazonQPropertiesFactory { get; set; }

    internal InnerConnectionS3PropertiesInputFactory S3PropertiesFactory { get; set; }

    internal InnerConnectionSparkEmrPropertiesInputFactory SparkEmrPropertiesFactory { get; set; }

    internal InnerConnectionLakehousePropertiesInputFactory LakehousePropertiesFactory { get; set; }

    internal InnerConnectionGluePropertiesInputFactory GluePropertiesFactory { get; set; }

    protected override Humidifier.DataZone.ConnectionTypes.ConnectionPropertiesInput Create()
    {
        var connectionPropertiesInputResult = CreateConnectionPropertiesInput();
        factoryAction?.Invoke(connectionPropertiesInputResult);

        return connectionPropertiesInputResult;
    }

    private Humidifier.DataZone.ConnectionTypes.ConnectionPropertiesInput CreateConnectionPropertiesInput()
    {
        var connectionPropertiesInputResult = new Humidifier.DataZone.ConnectionTypes.ConnectionPropertiesInput();

        return connectionPropertiesInputResult;
    }
    public override void CreateChildren(Humidifier.DataZone.ConnectionTypes.ConnectionPropertiesInput result)
    {
        base.CreateChildren(result);

        result.IamProperties ??= IamPropertiesFactory?.Build();
        result.HyperPodProperties ??= HyperPodPropertiesFactory?.Build();
        result.SparkGlueProperties ??= SparkGluePropertiesFactory?.Build();
        result.MlflowProperties ??= MlflowPropertiesFactory?.Build();
        result.AthenaProperties ??= AthenaPropertiesFactory?.Build();
        result.RedshiftProperties ??= RedshiftPropertiesFactory?.Build();
        result.WorkflowsMwaaProperties ??= WorkflowsMwaaPropertiesFactory?.Build();
        result.AmazonQProperties ??= AmazonQPropertiesFactory?.Build();
        result.S3Properties ??= S3PropertiesFactory?.Build();
        result.SparkEmrProperties ??= SparkEmrPropertiesFactory?.Build();
        result.LakehouseProperties ??= LakehousePropertiesFactory?.Build();
        result.GlueProperties ??= GluePropertiesFactory?.Build();
    }

} // End Of Class

